-- The SOLID-DRILL code key (Code keys -> Drilling -> SOLID-DRILL), from the ISCAR
-- e-catalog's SOLID-DRILL families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.soliddrill', $ck${"title": "SOLID-DRILL code key – solid carbide drills", "subtitle": "Solid carbide drills (SCD, three flute SCCD, pre-thread SCDT) and ECD-S2 chamfering and spot drilling tools", "example": "SCD 060-020-060 AP3N", "decoder": "solid-drill", "sections": [{"key": "t-family", "title": "Drill – family", "sample": "SCD", "rows": [{"code": "SCD", "meaning": "Solid carbide drill"}, {"code": "SCCD", "meaning": "Three flute solid carbide drill"}, {"code": "SCDT", "meaning": "Pre-thread solid carbide drill with coolant holes"}, {"code": "ECD-S2", "meaning": "Chamfering and spot drilling solid carbide tool"}]}, {"key": "t-dia", "title": "Drill – diameter", "sample": "060", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 060 = 6.0 mm)"}, {"code": "####", "meaning": "Drilling diameter x100 (e.g. 0330 = 3.30 mm)"}, {"code": "##", "meaning": "ECD-S2: diameter in mm"}]}, {"key": "t-length", "title": "Drill – length", "rows": [{"code": "###", "meaning": "Flute / usable length in mm (inferred)"}, {"code": "##", "meaning": "ECD-S2: overall length in mm"}]}, {"key": "t-height", "title": "Drill – shank", "rows": [{"code": "###", "meaning": "Shank diameter x10 (e.g. 060 = 6 mm)"}, {"code": "C##", "meaning": "ECD-S2: cylindrical shank diameter in mm"}]}, {"key": "t-line", "title": "Drill – line", "sample": "AP3N", "rows": [{"code": "AP3", "meaning": "DIN 6537, without coolant holes, 3xD"}, {"code": "AP4", "meaning": "DIN 6537, without coolant holes, 4xD"}, {"code": "AP5", "meaning": "Without coolant holes, 5xD"}, {"code": "AP6", "meaning": "DIN 6537, without coolant holes, 6xD"}, {"code": "AP3N", "meaning": "DIN 6537, without coolant holes, 3xD (N line)"}, {"code": "AP5N", "meaning": "DIN 6537, without coolant holes, 5xD (N line)"}, {"code": "ACP5", "meaning": "With coolant holes, 5xD"}, {"code": "ACP3N", "meaning": "DIN 6537, with coolant holes, 3xD (N line)"}, {"code": "ACP5N", "meaning": "DIN 6537, with coolant holes, 5xD (N line)"}, {"code": "ACP8N", "meaning": "With coolant holes, 8xD (N line)"}, {"code": "ACP3FL", "meaning": "With coolant holes, 3xD (North America only)"}, {"code": "ACP5FL", "meaning": "With coolant holes, 5xD (North America only)"}, {"code": "ACP8FL", "meaning": "With coolant holes, 8xD (North America only)"}, {"code": "AH5", "meaning": "For hard materials, 5xD"}, {"code": "PXC05", "meaning": "With coolant holes, 150° point angle, 5xD"}, {"code": "SXC16", "meaning": "Internal coolant channels, deep drilling 16xD"}, {"code": "SXC20", "meaning": "Internal coolant channels, 20xD"}, {"code": "SXC30", "meaning": "Internal coolant channels, 30xD"}, {"code": "SXC40", "meaning": "Internal coolant channels, 40xD"}, {"code": "SXC50", "meaning": "Internal coolant channels, 50xD"}, {"code": "IXC16", "meaning": "Internal coolant channels, 16xD, for ISO K materials"}, {"code": "IXC20", "meaning": "Internal coolant channels, 20xD, for ISO K materials"}, {"code": "IXC30", "meaning": "Internal coolant channels, 30xD, for ISO K materials"}, {"code": "FNPCD", "meaning": "PCD full nib insert, for composites (CFRP) and stacks"}, {"code": "WPCD", "meaning": "PCD insert, for composites (CFRP) and stacks"}, {"code": "CVD", "meaning": "CVD coated, for composites (CFRP) and stacks"}, {"code": "PICCO3D", "meaning": "PICCO, for Swiss-type and small CNC machines, 3xD"}, {"code": "ACP3", "meaning": "SCCD: three flute, with coolant holes, 3xD"}, {"code": "ACF3", "meaning": "SCCD: three flute flat head, with coolant holes, 3xD"}, {"code": "ACF5", "meaning": "SCCD: three flute flat head, with coolant holes, 5xD"}]}, {"key": "t-thread", "title": "Drill – thread", "rows": [{"code": "M#", "meaning": "SCDT: the thread the pre-thread hole is for (e.g. M8)"}]}, {"key": "t-angle", "title": "Tool – point angle", "rows": [{"code": "##", "meaning": "ECD-S2 point angle in degrees (60, 90)"}, {"code": "###", "meaning": "ECD-S2 point angle in degrees (120)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
